            d = dist((sx, sy), o)
            if bestd is None or d < bestd or (d == bestd and o < closest):
                bestd = d
                closest = o
        target = closest if closest else (sx, sy)

    if target is None:
        return [0, 0]

    best_move = (0, 0)
    best_score = None
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
